def current_time():
    return datetime.now().strftime("%H:%M:%S")


def draw_bounding_box(photo, label):
    """Same logic as live_demo.py: threshold the S channel and box the object."""
    PADDING = 20
    photo_hsv = cv.cvtColor(photo, cv.COLOR_BGR2HSV)
    photo_hsv_blur = cv.GaussianBlur(photo_hsv, (15, 15), 0)
    _, s, _ = cv.split(photo_hsv_blur)
    _, s_thresh = cv.threshold(s, 110, 255, cv.THRESH_BINARY)

    x, y, w, h = cv.boundingRect(s_thresh)
    if w == 0 or h == 0:          # nothing detected
        return photo

    y0 = max(0, y - PADDING)
    y1 = min(photo.shape[0], y + h + PADDING)
    x0 = max(0, x - PADDING)
    x1 = min(photo.shape[1], x + w + PADDING)

    cv.rectangle(photo, (x0, y0), (x1, y1), (0, 255, 0), 2)
    cv.putText(photo, str(label), (x0, max(20, y0 - 10)),
               cv.FONT_HERSHEY_SIMPLEX, 0.9, (0, 255, 0), 2)
    return photo


class ConfusionMatrixWindow(ctk.CTkToplevel):
    """Separate window: one Train button, the confusion matrix, accuracy and F1 score.
    The data path is read from the main window's CSV field when Train is pressed."""

    def __init__(self, app):
        super().__init__(app)
        self.app = app
        self.title("Confusion matrix")
        self.geometry("850x700")
        self.minsize(600, 500)

        self.grid_columnconfigure(0, weight=1)
        self.grid_rowconfigure(1, weight=1)

        # Top bar: train button + status
        top = ctk.CTkFrame(self, fg_color="transparent")
        top.grid(row=0, column=0, sticky="ew", padx=15, pady=(15, 5))
        top.grid_columnconfigure(1, weight=1)

        self.train_btn = ctk.CTkButton(top, text="Train & evaluate", width=180,
                                       command=self.start_evaluation)
        self.train_btn.grid(row=0, column=0, sticky="w")

        self.status = ctk.CTkLabel(top, text="Press train to evaluate the model on a 80/20 split.",
                                   text_color="gray60", anchor="w")
        self.status.grid(row=0, column=1, sticky="ew", padx=15)

        self.progress = ctk.CTkProgressBar(top, mode="indeterminate")
        self.progress.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(8, 0))
        self.progress.set(0)

        # Matrix box
        self.plot_box = ctk.CTkFrame(self, corner_radius=12, border_width=2)
        self.plot_box.grid(row=1, column=0, sticky="nsew", padx=15, pady=5)
        self.plot_box.grid_columnconfigure(0, weight=1)
        self.plot_box.grid_rowconfigure(0, weight=1)

        self.placeholder = ctk.CTkLabel(self.plot_box, text="No confusion matrix yet",
                                        text_color="gray60", font=ctk.CTkFont(size=16))
        self.placeholder.grid(row=0, column=0, sticky="nsew")
        self.canvas = None

        # Score tiles
        scores = ctk.CTkFrame(self, fg_color="transparent")
        scores.grid(row=2, column=0, sticky="ew", padx=15, pady=(5, 15))
        scores.grid_columnconfigure((0, 1), weight=1)
        self.acc_value = self._score_tile(scores, 0, "Accuracy")
        self.f1_value = self._score_tile(scores, 1, "F1 score (weighted)")

        # CTkToplevel sometimes opens behind the main window on Windows
        self.after(150, self._bring_to_front)

    def _score_tile(self, parent, col, title):
        tile = ctk.CTkFrame(parent)
        tile.grid(row=0, column=col, sticky="ew", padx=(0 if col == 0 else 8, 0))
        ctk.CTkLabel(tile, text=title, text_color="gray60").pack(pady=(10, 0))
        value = ctk.CTkLabel(tile, text="-", font=ctk.CTkFont(size=28, weight="bold"))
        value.pack(pady=(0, 10))
        return value

    def _bring_to_front(self):
        self.lift()
        self.focus_force()

    def start_evaluation(self):
        data_path = self.app.data_entry.get().strip()     # path from the main window
        self.train_btn.configure(state="disabled", text="Training…")
        self.status.configure(text=f"Training on {data_path}…", text_color="gray70")
        self.progress.start()
        threading.Thread(target=self._evaluation_worker, args=(data_path,), daemon=True).start()

    def _evaluation_worker(self, data_path):
        # Training runs in a thread; drawing must happen on the GUI thread (self.after)
        try:
            result = self.app.create_confusion_matrix(data_path)
            self.after(0, lambda: self._show_result(*result))
        except Exception as e:
            self.app.log(f"Confusion matrix failed: {e}")
            self.after(0, lambda: self.status.configure(text=f"Failed: {e}", text_color="#ef5350"))
        finally:
            self.after(0, self._evaluation_done)

    def _evaluation_done(self):
        self.progress.stop()
        self.progress.set(0)
        self.train_btn.configure(state="normal", text="Train & evaluate")

    def _show_result(self, classes, y_test, y_predicted, accuracy, f1):
        dark = ctk.get_appearance_mode() == "Dark"
        bg = "#2b2b2b" if dark else "#dbdbdb"     # matches CTkFrame default colours
        fg = "white" if dark else "black"

        fig = Figure(figsize=(6, 5), dpi=100, facecolor=bg)
        ax = fig.add_subplot(111)
        ConfusionMatrixDisplay.from_predictions(y_test, y_predicted, labels=classes,
                                                cmap="Blues", ax=ax, colorbar=True,
                                                xticks_rotation=45)
        ax.set_title("Confusion matrix (test set)", color=fg)
        ax.set_facecolor(bg)
        ax.xaxis.label.set_color(fg)
        ax.yaxis.label.set_color(fg)
        ax.tick_params(colors=fg)
        cbar_ax = fig.axes[-1]
        cbar_ax.tick_params(colors=fg)
        fig.tight_layout()

        # Replace the placeholder / previous plot
        self.placeholder.grid_forget()
        if self.canvas is not None:
            self.canvas.get_tk_widget().destroy()
        self.canvas = FigureCanvasTkAgg(fig, master=self.plot_box)
        self.canvas.draw()
        self.canvas.get_tk_widget().grid(row=0, column=0, sticky="nsew", padx=6, pady=6)

        self.acc_value.configure(text=f"{accuracy * 100:.1f} %")
        self.f1_value.configure(text=f"{f1:.3f}")
        self.status.configure(text=f"Evaluated on {len(y_test)} test samples.",
                              text_color="#66bb6a")


def collect_debug_frames():
    """Every module variable in calculate_parameters.py named last_* that holds an image.
    Add e.g. `last_threshold_image = ...` there and it shows up in the Live frames window."""
    return {name: value for name, value in vars(cp).items()
            if name.startswith("last_") and isinstance(value, np.ndarray) and value.ndim in (2, 3)}


class LiveFramesWindow(ctk.CTkToplevel):
    """Separate window that shows the intermediate images from calculate_parameters.py live.
    One tile per last_* image, laid out in a grid of COLUMNS wide."""

    COLUMNS = 2

    def __init__(self, app):
        super().__init__(app)
        self.app = app
        self.title("Live frames - calculate_parameters")
        self.geometry("1000x600")
        self.minsize(500, 350)

        self.grid_columnconfigure(0, weight=1)
        self.grid_rowconfigure(0, weight=1)

        self.grid_frame = ctk.CTkFrame(self, fg_color="transparent")
        self.grid_frame.grid(row=0, column=0, sticky="nsew", padx=15, pady=15)

        self.placeholder = ctk.CTkLabel(self.grid_frame,
                                        text="No frames yet - connect to the stream.\n"
                                             "Images come from last_* variables in calculate_parameters.py",
                                        text_color="gray60", font=ctk.CTkFont(size=15))
        self.placeholder.pack(expand=True)

        self.tiles = {}            # name -> (box frame, image label)
        self.after(150, self._bring_to_front)
        self.after(GUI_REFRESH_MS, self.update_frames)

    def _bring_to_front(self):
        self.lift()
        self.focus_force()

    def _build_tiles(self, names):
        # (Re)build the grid when the set of images changes
        for child in self.grid_frame.winfo_children():
            child.destroy()
        self.tiles = {}
        self.tile_sizes = {}       # name -> last image size, only resize when it really changes
        rows = (len(names) + self.COLUMNS - 1) // self.COLUMNS
        cols = min(self.COLUMNS, len(names))
        # Reset any rows/columns from a previous layout first
        old_rows, old_cols = getattr(self, "grid_rows", 0), getattr(self, "grid_cols", 0)
        for c in range(max(self.COLUMNS, old_cols)):
            self.grid_frame.grid_columnconfigure(c, weight=0, uniform="")
        for r in range(old_rows):
            self.grid_frame.grid_rowconfigure(r, weight=0, uniform="")

        # Only the columns/rows that actually hold a tile share the space equally.
        # (An empty column in the same uniform group would claim equal width and squeeze the tiles.)
        self.grid_rows, self.grid_cols = rows, cols
        for c in range(cols):
            self.grid_frame.grid_columnconfigure(c, weight=1, uniform="tile_col")
        for r in range(rows):
            self.grid_frame.grid_rowconfigure(r, weight=1, uniform="tile_row")

        for i, name in enumerate(names):
            r, c = divmod(i, self.COLUMNS)
            box = ctk.CTkFrame(self.grid_frame, corner_radius=12, border_width=2)
            box.grid(row=r, column=c, sticky="nsew", padx=5, pady=5)
            box.grid_columnconfigure(0, weight=1)
            box.grid_rowconfigure(1, weight=1)
            # "last_fft_image" -> "fft image"
            title = name.removeprefix("last_").replace("_", " ")
            title_label = ctk.CTkLabel(box, text=title, font=ctk.CTkFont(size=14, weight="bold"))
            title_label.grid(row=0, column=0, sticky="w", padx=12, pady=(8, 0))
            image_label = ctk.CTkLabel(box, text="")
            image_label.grid(row=1, column=0, sticky="nsew", padx=6, pady=6)
            self.tiles[name] = (title_label, image_label)

    def _cell_size(self, title_label):
        """Space available for an image, measured from the grid area (fixed by the window size),
        NOT from the tile itself. Measuring the tile caused a feedback loop: image grows the tile,
        tile measures bigger, image grows again... = jumping."""
        scaling = self.grid_frame._get_widget_scaling()
        area_w = self.grid_frame.winfo_width() / scaling
        area_h = self.grid_frame.winfo_height() / scaling
        title_h = title_label.winfo_height() / scaling + 8      # title + its top padding
        # per cell: minus tile padding (2*5), border + label padding (~2*10), safety margin
        cell_w = area_w / self.grid_cols - 10 - 20 - 4
        cell_h = area_h / self.grid_rows - 10 - 20 - 4 - title_h
        return max(cell_w, 50), max(cell_h, 50)

    def update_frames(self):
        if not self.winfo_exists():
            return

        with self.app.frame_lock:
            frames = self.app.latest_debug_frames

        if frames:
            if list(frames) != list(self.tiles):
                self._build_tiles(list(frames))

            for name, img in frames.items():
                title_label, label = self.tiles[name]
                # Make it uint8 first (cvtColor can't handle bool/float64 images)
                if img.dtype == bool:              # masks: True -> white
                    img = img.astype(np.uint8) * 255
                elif img.dtype != np.uint8:        # float/int images: stretch to 0-255
                    img = cv.normalize(img, None, 0, 255, cv.NORM_MINMAX, dtype=cv.CV_8U)
                # Convert to RGB for PIL: grayscale -> RGB, BGR (OpenCV) -> RGB
                if img.ndim == 2:
                    rgb = cv.cvtColor(img, cv.COLOR_GRAY2RGB)
                else:
                    rgb = cv.cvtColor(img, cv.COLOR_BGR2RGB)

                # Fit inside the grid cell (same DPI-scaling fix as the main live view)
                cell_w, cell_h = self._cell_size(title_label)
                fh, fw = rgb.shape[:2]
                scale = min(cell_w / fw, cell_h / fh)
                size = (max(1, int(fw * scale)), max(1, int(fh * scale)))
                # Ignore tiny (1-2 px) measurement wiggles, keep the previous size
                prev = self.tile_sizes.get(name)
                if prev and abs(prev[0] - size[0]) <= 2 and abs(prev[1] - size[1]) <= 2:
                    size = prev
                self.tile_sizes[name] = size

                ctk_img = ctk.CTkImage(light_image=Image.fromarray(rgb), size=size)
                label.configure(image=ctk_img)
                label.image = ctk_img          # keep a reference

        self.after(GUI_REFRESH_MS, self.update_frames)


